function UIWorldBossPlayerRankingsDialog:UpdateInfo(playerRankInfo)
    self.rankList = playerRankInfo.rankList
    if #self.rankList <= 0 then
        KTool.SetActive(self.EmptyNode, true)
        return
    end
    self.playerRank = playerRankInfo.playerRank
    self.percentageRank = playerRankInfo.percentageRank
    self.headScale = 0.31

    local listLength = #self.rankList
    local existRankData = listLength > 0
    KTool.SetActive(self.LayoutListAndMyselef, existRankData)
    CfUtils.SetActive(self.EmptyNode, not existRankData)

    if existRankData then
        self.LoopView:InitListView(listLength, Bind(self, self.InitCellByIndex))
        self:FillMeRank()
    end
end

function UIWorldBossPlayerRankingsDialog:FillMeRank()
    if not self.playerRank then
        return
    end
    self.playerRank.score = self.playerRank.hurt
    KTool.SetActive(self.MyRanking, true)
    local comp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local playerDojo = comp:GetPlayerDojo()
    for k, v in pairs(self.rankList) do
        if checkNumber(v.playerId) == checkNumber(playerDojo.playerId) then
            self.playerRank = v
            break
        end
    end
    local UIWorldBossPlayerRankNode = "Game.UI.FightReady.UIWorldBoss.UIWorldBossPlayerRankingsDialog.UIWorldBossPlayerRankNode"
    local scr = CfUtils.GetLuaScr(self.MyRanking, UIWorldBossPlayerRankNode)
    if scr then
        scr:Refresh(self.playerRank, true)

        scr:FillPercentageRank(self.percentageRank)
    end
end

function UIWorldBossPlayerRankingsDialog:InitCellByIndex(view, index)
    local cellData = self.rankList[index + 1]
    local cell = view:NewListViewItem("Cell")
    local cellCtrl = CfUtils.GetLuaScr(cell.gameObject, "Game.UI.FightReady.UIWorldBoss.UIWorldBossPlayerRankingsDialog.UIWorldBossPlayerRankNode")

    if cellCtrl then
        cellCtrl:Refresh(cellData, false, Vector3(self.headScale, self.headScale, 1))
    end

    return cell
end



return UIWorldBossPlayerRankingsDialog
